function machineToClean(graph: number[][], initial: number[]): number {
  const n = graph.length;
  let best = -1, bestCount = Infinity;
  for (const skip of [...initial].sort((a, b) => a - b)) {
    const seen = new Array(n).fill(false);
    const q = initial.filter(m => m !== skip);
    q.forEach(m => { seen[m] = true; });
    for (let h = 0; h < q.length; h++) {
      const u = q[h];
      for (let v = 0; v < n; v++) if (graph[u][v] && !seen[v]) { seen[v] = true; q.push(v); }
    }
    if (q.length < bestCount) { bestCount = q.length; best = skip; }
  }
  return best;
}

