class Solution:
    def machineToClean(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        best, best_count = -1, float("inf")
        for skip in sorted(initial):
            seen = [False] * n
            q = [m for m in initial if m != skip]
            for m in q:
                seen[m] = True
            h = 0
            while h < len(q):
                u = q[h]
                h += 1
                for v in range(n):
                    if graph[u][v] and not seen[v]:
                        seen[v] = True
                        q.append(v)
            if len(q) < best_count:
                best_count, best = len(q), skip
        return best

