function machineToClean(graph: number[][], initial: number[]): number {
  const n = graph.length;
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x: number): number => {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  };
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      if (graph[i][j]) parent[find(i)] = find(j);
  const size = new Array(n).fill(0), infected = new Array(n).fill(0);
  for (let i = 0; i < n; i++) size[find(i)]++;
  for (const m of initial) infected[find(m)]++;
  let best = Math.min(...initial), bestSave = 0;
  for (const m of initial) {
    const root = find(m);
    if (infected[root] !== 1) continue;
    const save = size[root];
    if (save > bestSave || (save === bestSave && m < best)) { bestSave = save; best = m; }
  }
  return best;
}

